static void run(Path directory) throws Exception {
    Files.createDirectories(directory);
    Path database = directory.resolve("host.db");
    long coldStart = System.nanoTime();
    try (HostStore store = new PersistentHostStore(new SqliteHostStorePersistence(database))) {
        metric("coldReadyMillis", millis(coldStart), 8_000);
        populate(store);
        measureQueries(store);
        measureAckAndReplay(store);
        measureTools();
    }
    measureArtifact(directory.resolve("artifacts"));
    long beforeGc = usedHeap();
    for (int index = 0; index < 3; index++) { System.gc(); Thread.sleep(250); }
    long afterGc = usedHeap();
    if (afterGc > beforeGc + Math.max(1L, beforeGc / 20)) fail("postGcGrowth", afterGc);
    long rss = processRss();
    metric("rssBytes", rss, 2L * ArtifactLimits.GIB);
    System.out.printf(Locale.ROOT,
            "{\"status\":\"passed\",\"sessions\":%d,\"transcriptItems\":%d,\"replayEvents\":%d,\"artifactBytes\":%d,\"clients\":2,\"activeRuns\":2,\"toolEffects\":16,\"postGcBytes\":%d}%n",
            SESSIONS, SESSIONS * ITEMS_PER_SESSION, REPLAY_EVENTS, ARTIFACT_BYTES, afterGc);
    System.out.println("STAGE6_PERFORMANCE_OK");
}

